-- Set first employee in each department as manager
UPDATE employees SET is_manager = TRUE, managed_dept = department
WHERE emp_code IN (
  SELECT MIN(emp_code) FROM employees GROUP BY department
);

-- Set HR department
UPDATE employees SET is_hr = TRUE WHERE department = 'الموارد البشريه';

